-- discord.gg/syncrypt (origem do script)
-- ============================================================================
--  Soult core: wait/spawn/task rastreados. Toda thread criada pelo Soult é guardada
--  para ser cancelada quando o hub é descarregado (antes nada podia ser parado).
-- ============================================================================
local Soult = { threads = {}, alive = true }
local _task = task
local function track(th)
	local list = Soult.threads
	list[#list + 1] = th
	if #list > 600 then
		local keep = {}
		for _, t in ipairs(list) do
			if type(t) == "thread" and coroutine.status(t) ~= "dead" then keep[#keep + 1] = t end
		end
		Soult.threads = keep
	end
	return th
end
local task = setmetatable({
	spawn = function(f, ...) return track(_task.spawn(f, ...)) end,
	delay = function(t, f, ...) return track(_task.delay(t, f, ...)) end,
	defer = function(f, ...) return track(_task.defer(f, ...)) end,
}, { __index = _task })
local wait = _task.wait
local spawn = function(f, ...) return track(_task.delay(0, f, ...)) end
local Spawn, Wait = spawn, wait
B.onUnload:connect(function()
	Soult.alive = false
	for _, th in ipairs(Soult.threads) do pcall(_task.cancel, th) end
	table.clear(Soult.threads)
	pcall(function()
		getgenv().OnFarm = false
		getgenv().AutoMaterial = false
	end)
end)


local function geniter(f, s, c)
	if type(f) ~= "function" then
		local mt = getmetatable(f)

		if type(mt) == "table" and mt.__iter then
			f, s, c = mt.__iter(f)
		elseif type(f) == "table" then
			f, s, c = next, f, nil
		end
	end

	return function()
		local r = table.pack(f(s, c))

		if r[1] == nil then
			return false
		end

		c = r[1]

		return true, table.unpack(r, 1, r.n)
	end
end

