-- ---------------------------------------------------------------- armas
-- Equipa a tool `name` da mochila (se existir e o humanoide estiver vivo).
EquipWeapon = function(name)
	if not name then
		return
	end

	local char = plr.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local tool = plr.Backpack:FindFirstChild(name)

	if hum and tool then
		hum:EquipTool(tool)
	end
end
-- Equipa a primeira arma cujo ToolTip é `tip` (Melee/Sword/Blox Fruit/Gun), sem re-equipar se já está na mão.
weaponSc = function(tip)
	local char = plr.Character

	if char then
		for _, child in ipairs(char:GetChildren()) do
			if child:IsA("Tool") and child.ToolTip == tip then
				return
			end
		end
	end

	for _, child in ipairs(plr.Backpack:GetChildren()) do
		if child:IsA("Tool") and child.ToolTip == tip then
			return EquipWeapon(child.Name)
		end
	end
end

