-- Trava o mob na posição onde foi visto (atributo "Locked") e puxa os vizinhos (BringEnemy).
local function lockMob(mob)
	local hrp = mob:FindFirstChild("HumanoidRootPart")

	if not hrp then
		return false
	end

	if not mob:GetAttribute("Locked") then
		mob:SetAttribute("Locked", hrp.CFrame)
	end

	PosMon = mob:GetAttribute("Locked").Position
	BringEnemy()

	return true
end
