local function holdingFruit()
	local char = plr.Character
	local tool = char and char:FindFirstChildOfClass("Tool")

	return tool ~= nil and tool.ToolTip == "Blox Fruit"
end
local ORBIT = {
	{ 0, 30, 25 },
	{ 25, 30, 0 },
	{ -25, 30, 0 },
	{ 0, 30, 25 },
	{ -25, 30, 0 }
}
-- Com RandomCFrame ligado, circula o mob (esquiva) com `delay` entre cada ponto.
local function orbit(mob, delay)
	if not RandomCFrame then
		return
	end

	for _, o in ipairs(ORBIT) do
		wait(delay)

		local hrp = mob:FindFirstChild("HumanoidRootPart")

		if not hrp then
			return
		end

		_tp(hrp.CFrame * CFrame.new(o[1], o[2], o[3]))
	end
end
local DEFAULT_SKILLS = { "Z", "X", "C", "V", "F" }
-- Usa as skills escolhidas (_G.SelectedMasterySkills: lista ou mapa) com a arma `kind`.
local function castMastery(kind)
	local selected = _G.SelectedMasterySkills

	if type(selected) ~= "table" then
		selected = DEFAULT_SKILLS
	end

	for k, v in pairs(selected) do
		if type(k) == "number" then
			Useskills(kind, v)
		elseif type(k) == "string" and v == true then
			Useskills(kind, k)
		end
	end
end

