t9.Kill = function(mob, on)
	if not (mob and on) or not lockMob(mob) then
		return
	end

	EquipWeapon(_G.SelectWeapon)

	local cf = mob.HumanoidRootPart.CFrame

	if holdingFruit() then
		_tp(cf * CFrame.new(0, 30, 0) * CFrame.Angles(0, math.rad(90), 0))
	else
		_tp(cf * CFrame.new(0, 10, 0) * CFrame.Angles(0, math.rad(180), 0))
	end

	orbit(mob, 0.5)
end
