-- Ataque a monstros marinhos: sobe e desce (sem tween) para escapar do dano.
t9.KillSea = function(mob, on)
	if not (mob and on) or not lockMob(mob) then
		return
	end

	EquipWeapon(_G.SelectWeapon)

	local cf = mob.HumanoidRootPart.CFrame

	if holdingFruit() then
		_tp(cf * CFrame.new(0, 30, 0) * CFrame.Angles(0, math.rad(90), 0))
	else
		notween(cf * CFrame.new(0, 50, 8))
		wait(0.85)

		local hrp = mob:FindFirstChild("HumanoidRootPart")

