BringEnemy = function(p24)
	if not _B then
		return
	end

	if not p24 then
		local HumanoidRootPart = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")

		if not HumanoidRootPart then
			return
		end

		local huge = math.huge

		for _, child in ipairs(workspace.Enemies:GetChildren()) do
			local Humanoid = child:FindFirstChildOfClass("Humanoid")
			local HumanoidRootPart2 = child:FindFirstChild("HumanoidRootPart")

			if Humanoid and HumanoidRootPart2 and Humanoid.Health > 0 then
				local Magnitude = (HumanoidRootPart2.Position - HumanoidRootPart.Position).Magnitude

				if Magnitude < huge then
					huge = Magnitude
					p24 = child
				end
			end
		end

		if not p24 then
			return
		end
	end

	local u34 = false

	local function v35(p25)
		local Humanoid = p25:FindFirstChildOfClass("Humanoid")
		local HumanoidRootPart = p25:FindFirstChild("HumanoidRootPart")

		return Humanoid and HumanoidRootPart and Humanoid.Health > 0, HumanoidRootPart, Humanoid
	end
	local function v38(p26)
		if isnetworkowner then
			return isnetworkowner(p26)
		end

		return p26.ReceiveAge == 0 and not p26.Anchored and p26.Velocity.Magnitude > 0
	end

	pcall(function()
		if sethiddenproperty then
			sethiddenproperty(plr, "SimulationRadius", math.huge)
		end

		local Position = p24.HumanoidRootPart.Position

		for _, child in ipairs(workspace.Enemies:GetChildren()) do
			if child ~= p24 then
				local v42, v43, v44 = v35(child)

				if v42 and child.Name == p24.Name then
					local Magnitude = (v43.Position - Position).Magnitude

					if Magnitude <= 3000 then
						if not v43:FindFirstChild("BodyVelocity") then
							local BodyVelocity = Instance.new("BodyVelocity")

							BodyVelocity.Name = "BodyVelocity"
							BodyVelocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
							BodyVelocity.Velocity = Vector3.zero
							BodyVelocity.Parent = v43
						end

						if Magnitude <= 10 then
							u34 = true
						end

						if not u34 and v38(v43) then
							v43.CFrame = CFrame.new(Position)
						end

						v43.CanCollide = false
						v44.WalkSpeed = 0
						v44.JumpPower = 0
					end
				end
			end
		end

		if p24 and p24:FindFirstChild("HumanoidRootPart") then
			p24.HumanoidRootPart.CanCollide = false
			p24.Humanoid.WalkSpeed = 0
			p24.Humanoid.JumpPower = 0
		end
	end)
end

-- ---------------------------------------------------------------- skills
local SKILL_KEYS = { Z = true, X = true, C = true, V = true, F = true, Y = true }
local function toolNameByTip(tip)
	for _, container in ipairs({ plr.Character, plr.Backpack }) do
		if container then
			for _, tool in ipairs(container:GetChildren()) do
				if tool:IsA("Tool") and tool.ToolTip == tip then
					return tool.Name
				end
			end
		end
	end
end
-- A skill `key` da arma `tip` está pronta (sem cooldown na GUI)?
local function skillReady(tip, key)
	local name = toolNameByTip(tip)
	local main = plr.PlayerGui:FindFirstChild("Main")
	local skills = main and main:FindFirstChild("Skills")
	local frame = name and skills and skills:FindFirstChild(name)

	if not frame then
		return true
	end

	local slot = frame:FindFirstChild(key)

	if not slot then
		return false
	end

	local title = slot:FindFirstChild("Title")

	if title and title:IsA("TextLabel") and title.TextColor3.R < 0.5 then
		return false
	end

	local cooldown = slot:FindFirstChild("Cooldown")

	if cooldown and (cooldown.Size.X.Scale > 0 or cooldown.AbsoluteSize.X > 0) then
		return false
	end

	return true
end
local WEAPON_KINDS = { Melee = true, Sword = true, ["Blox Fruit"] = true, Gun = true }

-- Equipa a arma `kind` e aperta a tecla `key` se a skill estiver pronta.
Useskills = function(kind, key)
	if WEAPON_KINDS[kind] then
		weaponSc(kind)

		if not SKILL_KEYS[key] or not skillReady(kind, key) then
			return
		end
	elseif not (kind == "nil" and key == "Y") then
		return
	end

	vim1:SendKeyEvent(true, key, false, game)
	vim1:SendKeyEvent(false, key, false, game)
end

-- Redireciona o alvo do mouse (MousePos) nos RemoteEvents de skill enquanto os modos de mira/farm estão ligados.
do
	pcall(function()
		local mt = getrawmetatable(game)
		local __namecall = mt.__namecall

		setreadonly(mt, false)

		local hook
		hook = newcclosure(function(...)
			local method = getnamecallmethod()
			local args = table.pack(...)

			if Soult.alive and tostring(method) == "FireServer" and tostring(args[1]) == "RemoteEvent" and tostring(args[2]) ~= "true" and tostring(args[2]) ~= "false" then
				if _G.FarmMastery_G and not SoulGuitar or _G.FarmMastery_Dev or _G.FarmBlazeEM or _G.Prehis_Skills or _G.SeaBeast1 or _G.FishBoat or _G.PGB or _G.Leviathan1 or _G.Complete_Trials or _G.AimMethod and ABmethod == "Aim Player" or _G.AimMethod and ABmethod == "Nearest Aim" then
					args[2] = MousePos

					return __namecall(unpack(args, 1, args.n))
				end
			end

			return __namecall(...)
		end)
		mt.__namecall = hook
		B.onUnload:connect(function()
			pcall(function()
				setreadonly(mt, false)
				mt.__namecall = __namecall
			end)
		end)
	end)
end

-- Primeiro mob vivo com nome em `names` (string ou lista) no ReplicatedStorage ou em workspace.Enemies.
GetConnectionEnemies = function(names)
	local function match(name)
		if typeof(names) == "table" then
			return table.find(names, name) ~= nil
		end

		return name == names
	end

	for _, container in ipairs({ replicated, workspace.Enemies }) do
		for _, child in ipairs(container:GetChildren()) do
			if child:IsA("Model") and match(child.Name) then
				local Humanoid = child:FindFirstChild("Humanoid")

				if Humanoid and Humanoid.Health > 0 then
					return child
				end
			end
		end
	end
end
-- Modo "pouca CPU": tira água/sombras/efeitos e simplifica materiais.
-- (BUG corrigido: a original atribuía um número a MeshPart.TextureID e quebrava no primeiro MeshPart; agora cada item é protegido)
LowCpu = function()
	pcall(function()
		local Terrain = workspace.Terrain

		Terrain.WaterWaveSize = 0
		Terrain.WaterWaveSpeed = 0
		Terrain.WaterReflectance = 0
		Terrain.WaterTransparency = 0
		Lighting.GlobalShadows = false
		Lighting.FogEnd = 9e9
		Lighting.Brightness = 0
		settings().Rendering.QualityLevel = "Level01"
	end)

	for _, d in ipairs(game:GetDescendants()) do
		pcall(function()
			if d:IsA("MeshPart") then
				d.Material = Enum.Material.Plastic
				d.Reflectance = 0
				d.TextureID = ""
			elseif d:IsA("BasePart") then
				d.Material = Enum.Material.Plastic
				d.Reflectance = 0
			elseif d:IsA("Decal") or d:IsA("Texture") then
				d.Transparency = 1
			elseif d:IsA("ParticleEmitter") or d:IsA("Trail") then
				d.Lifetime = NumberRange.new(0)
			elseif d:IsA("Explosion") then
				d.BlastPressure = 1
				d.BlastRadius = 1
			elseif d:IsA("Fire") or d:IsA("SpotLight") or d:IsA("Smoke") or d:IsA("Sparkles") then
				d.Enabled = false
			end
		end)
	end

	for _, child in ipairs(Lighting:GetChildren()) do
		if child:IsA("BlurEffect") or child:IsA("SunRaysEffect") or child:IsA("ColorCorrectionEffect") or child:IsA("BloomEffect") or child:IsA("DepthOfFieldEffect") then
			child.Enabled = false
		end
	end
end
