-- Server hop: procura um servidor com < 12 jogadores (páginas aleatórias do __ServerBrowser) e teleporta.
-- (Melhorado: ignora o servidor atual, tolera falhas por página e para no primeiro teleporte em vez de disparar vários.)
Hop = function()
	pcall(function()
		for page = math.random(1, math.random(40, 75)), 100 do
			local ok, servers = pcall(function()
				return replicated.__ServerBrowser:InvokeServer(page)
			end)

			if ok and type(servers) == "table" then
				for jobId, info in pairs(servers) do
					local count = type(info) == "table" and tonumber(info.Count)

					if count and count < 12 and jobId ~= game.JobId then
						TeleportService:TeleportToPlaceInstance(game.PlaceId, jobId, plr)
						task.wait(2)

						return
					end
				end
			end

			task.wait(0.2)
		end
	end)
end

