					t33[v673][v674] = t33[v673][v674] or {}
					t33[v673][v674][#t33[v673][v674] + 1] = v672
				end
			end
		end

		local t34 = {}

		for k in pairs(t33) do
			t34[#t34 + 1] = k
		end

		table.sort(t34)

		for _, v1 in ipairs(t34) do
			local v679 = t33[v1]
			local t35 = {}
			local v681, v682, v683 = pairs(v679)

			for k in v681, v682, v683 do
				t35[#t35 + 1] = k
			end

