-- Auto Train Drago v4.
-- Reescrito: o original tinha ~12.700 linhas geradas pelo descompilador (o mesmo laço duplicado 190x); a lógica real é esta.
do
	local DRAGO_SPOT = CFrame.new(4620.61572265625, 1002.2954711914062, 399.08688354492188)
	local targets = { "Venomous Assailant", "Hydra Enforcer" }

	spawn(function()
