				if not _G.TrainDrago then
					return
				end

				for _ = 1, #targets do
					local char = plr.Character

					if char:FindFirstChild("RaceEnergy").Value == 1 then
						-- energia cheia: ativa a transformação, compra o upgrade e volta ao ponto
						vim1:SendKeyEvent(true, "Y", true, game)
						replicated.Remotes.CommF_:InvokeServer("UpgradeRace", "Buy", 2)
						vim1:SendKeyEvent(false, "Y", true, game)
						_tp(DRAGO_SPOT)
					elseif char:FindFirstChild("RaceTransformed").Value == false then
						local mob = GetConnectionEnemies(targets)

						if not mob then
							_tp(DRAGO_SPOT)
						else
							repeat
								wait()
								t9.Kill(mob, _G.TrainDrago)
							until _G.TrainDrago == false or not mob.Parent or not t9.Alive(mob)
						end
					end
				end
			end)
		end
	end)
end

